solution:
import { useState, useCallback } from 'react';

export function useDragDrop<T>(initialItems: T[]) {
  const [items, setItems] = useState(initialItems);
  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);

  const onDragStart = useCallback((index: number) => {
    setDraggingIndex(index);
  }, []);

  const onDragOver = useCallback((_index: number) => {}, []);

  const onDrop = useCallback((dropIndex: number) => {
    setDraggingIndex(prev => {
      if (prev === null || prev === dropIndex) return null;
      setItems(current => {
        const next = [...current];
        const [dragged] = next.splice(prev, 1);
        next.splice(dropIndex, 0, dragged);
        return next;
      });
      return null;
    });
  }, []);

  return { items, onDragStart, onDragOver, onDrop, draggingIndex };
}
